/**
 * baseline.js — Nearest-Elevator Baseline Algorithm
 *
 * This is the reference algorithm that participants must try to outperform.
 * It selects the elevator that is closest to the requesting floor, with a
 * penalty applied to elevators that are already at capacity.
 *
 * DO NOT EDIT THIS FILE. Edit src/algorithms/participant.js instead.
 */

/**
 * Assign an elevator to handle a new passenger request.
 *
 * @param {Object}   request           The incoming passenger request.
 * @param {number}   request.origin    Floor where passengers are waiting.
 * @param {number}   request.dest      Floor they want to go to.
 * @param {number}   request.count     Number of passengers in the group.
 *
 * @param {Object[]} elevators         Read-only snapshots of both elevators.
 * @param {number}   elevators[].id          0 (A) or 1 (B)
 * @param {number}   elevators[].floor       Current floor index.
 * @param {string}   elevators[].state       ElevatorState string.
 * @param {number}   elevators[].occupancy   Passengers currently inside.
 * @param {number}   elevators[].capacity    Maximum capacity (always 10).
 * @param {number[]} elevators[].destinations  Floors this elevator is committed to visit.
 * @param {number}   elevators[].assignmentCount  Pending pickups assigned.
 *
 * @param {number}   currentTime       Current simulation time in seconds.
 *
 * @returns {number}  0 to assign Elevator A, 1 to assign Elevator B.
 */
export function assignElevator(request, elevators, currentTime) {
  let bestId   = 0;
  let minScore = Infinity;

  for (const el of elevators) {
    // Primary factor: floor distance.
    let score = Math.abs(el.floor - request.origin);

    // Penalise elevators that are already full.
    // This avoids assigning to a car that cannot pick anyone up.
    if (el.occupancy >= el.capacity) {
      score += 50;
    }

    // Penalise elevators with many pending assignments so workload spreads.
    score += el.assignmentCount * 2;

    if (score < minScore) {
      minScore = score;
      bestId   = el.id;
    }
  }

  return bestId;
}
